import net from 'node:net';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { startServer } from './testing/server.ts';

const dir = mkdtempSync(join(tmpdir(), 'repro-'));
const server = await startServer(dir);
const url = new URL(server.origin);

function rawRequest({ useChunked, mode }) {
  return new Promise((resolve) => {
    const body = 'x'.repeat(1_000_001);
    const sock = net.connect(Number(url.port), url.hostname);
    let received = Buffer.alloc(0);
    let errored = null;
    sock.on('error', (e) => { errored = e; });
    sock.on('connect', () => {
      const head = useChunked
        ? `POST /api/ideas HTTP/1.1\r\nHost: localhost\r\nTransfer-Encoding: chunked\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n`
        : `POST /api/ideas HTTP/1.1\r\nHost: localhost\r\nContent-Length: ${Buffer.byteLength(body)}\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n`;
      sock.write(head);
      if (mode === 'all') {
        if (useChunked) sock.write(`${body.length.toString(16)}\r\n${body}\r\n0\r\n\r\n`);
        else sock.write(body);
      } else if (mode === 'chunks-immediate') {
        let off = 0;
        const step = 200_000;
        function sendMore() {
          while (off < body.length) {
            const piece = body.slice(off, off + step);
            off += piece.length;
            if (useChunked) sock.write(`${piece.length.toString(16)}\r\n${piece}\r\n`);
            else { if (!sock.write(piece)) { sock.once('drain', sendMore); return; } }
          }
          if (useChunked) sock.write('0\r\n\r\n');
        }
        sendMore();
      }
    });
    sock.on('data', (d) => { received = Buffer.concat([received, d]); });
    sock.on('close', () => {
      resolve({ errored: errored?.code ?? null, head: received.toString('latin1').split('\r\n\r\n')[0], bytes: received.length });
    });
  });
}

for (const useChunked of [false, true]) {
  for (const mode of ['all', 'chunks-immediate']) {
    console.log(useChunked ? 'chunked' : 'content-length', mode, await rawRequest({ useChunked, mode }));
  }
}
await server.stop();

